const body = $input.first().json;
const base = $('Set - Loader Config').first().json.base_currency;
const fetchedAt = new Date().toISOString();
const rows = Object.entries(body.data || {}).map(([target, rate]) => ({
  base_currency: base,
  target_currency: target,
  rate: typeof rate === 'number' ? rate : Number(rate),
  fetched_at: fetchedAt,
}));
return [{ json: { rows } }];

const row = $input.item.json;
return {
  json: {
    workflow: 'Daily Currency Rate Loader',
    warning: 'ROW_SKIPPED_INVALID',
    reason: 'Row failed per-field validation (missing currency code, non-numeric/NaN rate, or missing fetched_at) and was skipped without upserting.',
    base_currency: row.base_currency ?? null,
    target_currency: row.target_currency ?? null,
    rate: row.rate ?? null,
    fetched_at: row.fetched_at ?? null,
    skipped_at: new Date().toISOString(),
  },
};

// Single convergence point for all three loader failure branches. Classifies
// which one fired and emits one structured error record.
//
// The classification below is total - every inbound item lands in exactly one
// stage - because the three branches carry structurally different items:
//   HTTP error output       -> n8n's error shape (has `error` or `message`)
//   IF - Response OK false  -> the raw API body (no `rows` key; Code - Rates To
//                              Rows has not run on this branch)
//   IF - Rows Valid false   -> { rows: [...] } from Code - Rates To Rows
const item = $input.first().json;

// Set - Loader Config always runs before every failure point, but guard anyway
// so a classification failure can never mask the original error.
let base_currency = null;
try {
  base_currency = $('Set - Loader Config').first().json.base_currency;
} catch (e) {
  base_currency = null;
}

let failure_stage;
let error_message;

if (item && (item.error !== undefined || item.message !== undefined)) {
  failure_stage = 'HTTP_FETCH';
  const raw = item.error && item.error.message ? item.error.message : item.message;
  error_message = 'freecurrencyapi request failed: ' + (raw || 'no error message returned');
} else if (!item || !Array.isArray(item.rows)) {
  failure_stage = 'API_RESPONSE';
  error_message = 'freecurrencyapi responded without usable rate data (empty or missing "data" object)';
} else {
  failure_stage = 'ROW_VALIDATION';
  error_message = 'Transformed rows failed validation: expected a non-empty array where every row has base_currency, target_currency, a numeric rate and fetched_at (got ' + item.rows.length + ' row(s))';
}

return [{
  json: {
    workflow: 'Daily Currency Rate Loader',
    failure_stage,
    error_message,
    base_currency,
    failed_at: new Date().toISOString(),
  },
}];
